/**
 * TimeSpeed is an enumeration of time speeds. These are supported by TimeControlNode, when it includes speed controls.
 *
 * @author Jesse Greenberg (PhET Interactive Simulations)
 * @author Chris Malley (PixelZoom, Inc.)
 */
import '../../globals.js';
import Enumeration from '../../phet-core/js/Enumeration.js';
import EnumerationValue from '../../phet-core/js/EnumerationValue.js';
import sceneryPhet from './sceneryPhet.js';
class TimeSpeed extends EnumerationValue {
}
TimeSpeed.FAST = new TimeSpeed();
TimeSpeed.NORMAL = new TimeSpeed();
TimeSpeed.SLOW = new TimeSpeed();
// Gets a list of keys, values and mapping between them. For use in EnumerationProperty and PhET-iO
TimeSpeed.enumeration = new Enumeration(TimeSpeed);
export default TimeSpeed;
sceneryPhet.register('TimeSpeed', TimeSpeed);
